namespace ghidra.file.formats.android.art;

using ghidra.app.util.bin;
using ghidra.app.util.bin;
using ghidra.app.util.bin;
using ghidra.app.util.importer;
using ghidra.app.util.opinion;
using ghidra.file.analyzers;
using ghidra.file.formats.android.oat;
using ghidra.program.model.address;
using ghidra.program.model.address;
using ghidra.program.model.data;
using ghidra.program.model.listing;
using ghidra.util.task;

public class ArtAnalyzer : FileFormatAnalyzer {

	/* @Override */
	public string getName() {
		return "Android ART Header Format";
	}

	/* @Override */
	public bool getDefaultEnablement(Program program) {
		return true;
	}

	/* @Override */
	public string getDescription() {
		return "Analyzes the Android ART information in this program.";
	}

	/* @Override */
	public bool canAnalyze(Program program) {
		return ArtConstants.isART(program)
		//HACK:
		//Make analyzer appear after ART is merged with OAT program
		//Currently, analyzers will not recognize the new ART block being added
			|| OatUtilities.isOAT(program);
	}

	/* @Override */
	public bool isPrototype() {
		return false;
	}

	/* @Override */
	public bool analyze(Program program, AddressSetView set, TaskMonitor monitor, MessageLog log)
    {
		Address address = ArtConstants.findART(program);

		if (address == null) {//ART does not exist so quit, could be OAT
			return false;
		}

		ByteProvider provider = new MemoryByteProvider(program.getMemory(), address);
		BinaryReader reader = new BinaryReader(provider, !program.getLanguage().isBigEndian());

		try {
			ArtHeader header = ArtHeaderFactory.newArtHeader(reader);

			DataType headerDataType = header.toDataType();

			//only set "image base" when ART header not defined at "image begin"
			//---this only happens when ART is "added to" OAT program
			Address imageBase = toAddr(program, header.getImageBegin());

			if (BinaryLoader.BINARY_NAME.equals(program.getExecutableFormat())) {
				program.setImageBase(imageBase, true);
				createData(program, imageBase, headerDataType);
			}
			else {
				createData(program, address, headerDataType);
			}

			header.markup(program, monitor);

			return true;
		}
		catch (UnsupportedArtVersionException e) {
			log.appendException(e);
		}
		catch (Exception e) {
			throw e;
		}
		return false;
	}

}
